module GameData
  class TrainerType
    attr_reader :id
    attr_reader :real_name
    attr_reader :gender
    attr_reader :base_money
    attr_reader :skill_level
    attr_reader :flags
    attr_reader :intro_BGM
    attr_reader :battle_BGM
    attr_reader :victory_BGM
    attr_reader :pbs_file_suffix

    DATA = {}
    DATA_FILENAME = "trainer_types.dat"
    PBS_BASE_FILENAME = "trainer_types"

    SCHEMA = {
      "SectionName" => [:id,          "m"],
      "Name"        => [:real_name,   "s"],
      "Gender"      => [:gender,      "e", {"Male" => 0, "male" => 0, "M" => 0, "m" => 0, "0" => 0,
                                            "Female" => 1, "female" => 1, "F" => 1, "f" => 1, "1" => 1,
                                            "Unknown" => 2, "unknown" => 2, "Other" => 2, "other" => 2,
                                            "Mixed" => 2, "mixed" => 2, "X" => 2, "x" => 2, "2" => 2}],
      "BaseMoney"   => [:base_money,  "u"],
      "SkillLevel"  => [:skill_level, "u"],
      "Flags"       => [:flags,       "*s"],
      "IntroBGM"    => [:intro_BGM,   "s"],
      "BattleBGM"   => [:battle_BGM,  "s"],
      "VictoryBGM"  => [:victory_BGM, "s"]
    }

    extend ClassMethodsSymbols
    include InstanceMethods

    def self.editor_properties
      gender_array = []
      self.schema["Gender"][2].each { |key, value| gender_array[value] = key if !gender_array[value] }
      return [
        ["ID",         ReadOnlyProperty,               _INTL("ID of this Trainer Type (used as a symbol like :XXX).")],
        ["Name",       StringProperty,                 _INTL("Name of this Trainer Type as displayed by the game.")],
        ["Gender",     EnumProperty.new(gender_array), _INTL("Gender of this Trainer Type.")],
        ["BaseMoney",  LimitProperty.new(9999),        _INTL("Player earns this much money times the highest level among the trainer's Pokémon.")],
        ["SkillLevel", LimitProperty2.new(9999),       _INTL("Skill level of this Trainer Type.")],
        ["Flags",      StringListProperty,             _INTL("Words/phrases that can be used to make trainers of this type behave differently to others.")],
        ["IntroBGM",   BGMProperty,                    _INTL("BGM played before battles against trainers of this type.")],
        ["BattleBGM",  BGMProperty,                    _INTL("BGM played in battles against trainers of this type.")],
        ["VictoryBGM", BGMProperty,                    _INTL("BGM played when player wins battles against trainers of this type.")]
      ]
    end

    def self.check_file(tr_type, path, optional_suffix = "", suffix = "")
      tr_type_data = self.try_get(tr_type)
      return nil if tr_type_data.nil?
      # Check for files
      if optional_suffix && !optional_suffix.empty?
        ret = path + tr_type_data.id.to_s + optional_suffix + suffix
        return ret if pbResolveBitmap(ret)
      end
      ret = path + tr_type_data.id.to_s + suffix
      return (pbResolveBitmap(ret)) ? ret : nil
    end

    def self.charset_filename(tr_type)
      return self.check_file(tr_type, "Graphics/Characters/trainer_")
    end

    def self.charset_filename_brief(tr_type)
      ret = self.charset_filename(tr_type)
      ret&.slice!("Graphics/Characters/")
      return ret
    end

    def self.front_sprite_filename(tr_type)
      return self.check_file(tr_type, "Graphics/Trainers/")
    end

    def self.player_front_sprite_filename(tr_type)
      outfit = ($player) ? $player.outfit : 0
      return self.check_file(tr_type, "Graphics/Trainers/", sprintf("_%d", outfit))
    end

    def self.back_sprite_filename(tr_type)
      return self.check_file(tr_type, "Graphics/Trainers/", "", "_back")
    end

    def self.player_back_sprite_filename(tr_type)
      outfit = ($player) ? $player.outfit : 0
      return self.check_file(tr_type, "Graphics/Trainers/", sprintf("_%d", outfit), "_back")
    end

    def self.map_icon_filename(tr_type)
      return self.check_file(tr_type, "Graphics/UI/Town Map/player_")
    end

    def self.player_map_icon_filename(tr_type)
      outfit = ($player) ? $player.outfit : 0
      return self.check_file(tr_type, "Graphics/UI/Town Map/player_", sprintf("_%d", outfit))
    end

    def initialize(hash)
      @id              = hash[:id]
      @real_name       = hash[:real_name]       || "Unnamed"
      @gender          = hash[:gender]          || 2
      @base_money      = hash[:base_money]      || 30
      @skill_level     = hash[:skill_level]     || @base_money
      @flags           = hash[:flags]           || []
      @intro_BGM       = hash[:intro_BGM]
      @battle_BGM      = hash[:battle_BGM]
      @victory_BGM     = hash[:victory_BGM]
      @pbs_file_suffix = hash[:pbs_file_suffix] || ""
    end

    # @return [String] the translated name of this trainer type
    def name
      return pbGetMessageFromHash(MessageTypes::TRAINER_TYPE_NAMES, @real_name)
    end

    def male?;   return @gender == 0; end
    def female?; return @gender == 1; end

    def has_flag?(flag)
      return @flags.any? { |f| f.downcase == flag.downcase }
    end

    alias __orig__get_property_for_PBS get_property_for_PBS unless method_defined?(:__orig__get_property_for_PBS)
    def get_property_for_PBS(key)
      key = "SectionName" if key == "ID"
      ret = __orig__get_property_for_PBS(key)
      ret = nil if key == "SkillLevel" && ret == @base_money
      return ret
    end
  end
end

#===============================================================================
# Trainer class for the player
#===============================================================================
class Player < Trainer
  # @return [Integer] the character ID of the player
  attr_reader   :character_ID
  # @return [Integer] the player's outfit
  attr_reader   :outfit
  # @return [Array<Boolean>] the player's Gym Badges (true if owned)
  attr_accessor :badges
  # @return [Integer] the player's money
  attr_reader   :money
  # @return [Integer] the player's Game Corner coins
  attr_reader   :coins
  # @return [Integer] the player's battle points
  attr_reader   :battle_points
  # @return [Integer] the player's soot
  attr_reader   :soot
  # @return [Pokedex] the player's Pokédex
  attr_reader   :pokedex
  # @return [Boolean] whether the Pokédex has been obtained
  attr_accessor :has_pokedex
  # @return [Boolean] whether the Pokégear has been obtained
  attr_accessor :has_pokegear
  # @return [Boolean] whether the player has running shoes (i.e. can run)
  attr_accessor :has_running_shoes
  # @return [Boolean] whether the player has an innate ability to access Pokémon storage
  attr_accessor :has_box_link
  # @return [Boolean] whether the creator of the Pokémon Storage System has been seen
  attr_accessor :seen_storage_creator
  # @return [Boolean] whether the effect of Exp All applies innately
  attr_accessor :has_exp_all
  # @return [Boolean] whether Mystery Gift can be used from the load screen
  attr_accessor :mystery_gift_unlocked
  # @return [Array<Array>] downloaded Mystery Gift data
  attr_accessor :mystery_gifts

  def initialize(name, trainer_type)
    super
    @character_ID          = 0
    @outfit                = 0
    @badges                = [false] * 8
    @money                 = GameData::Metadata.get.start_money
    @coins                 = 0
    @battle_points         = 0
    @soot                  = 0
    @pokedex               = Pokedex.new
    @has_pokedex           = false
    @has_pokegear          = false
    @has_running_shoes     = false
    @has_box_link          = false
    @seen_storage_creator  = false
    @has_exp_all           = false
    @mystery_gift_unlocked = false
    @mystery_gifts         = []
  end

  #=============================================================================

  def character_ID=(value)
    return if @character_ID == value
    @character_ID = value
    $game_player&.refresh_charset
  end

  def outfit=(value)
    return if @outfit == value
    @outfit = value
    $game_player&.refresh_charset
  end

  def trainer_type
    return GameData::PlayerMetadata.get(@character_ID || 1).trainer_type
  end

  # Sets the player's money. It can not exceed {Settings::MAX_MONEY}.
  # @param value [Integer] new money value
  def money=(value)
    validate value => Integer
    @money = value.clamp(0, Settings::MAX_MONEY)
  end

  # Sets the player's coins amount. It can not exceed {Settings::MAX_COINS}.
  # @param value [Integer] new coins value
  def coins=(value)
    validate value => Integer
    @coins = value.clamp(0, Settings::MAX_COINS)
  end

  # Sets the player's Battle Points amount. It can not exceed
  # {Settings::MAX_BATTLE_POINTS}.
  # @param value [Integer] new Battle Points value
  def battle_points=(value)
    validate value => Integer
    @battle_points = value.clamp(0, Settings::MAX_BATTLE_POINTS)
  end

  # Sets the player's soot amount. It can not exceed {Settings::MAX_SOOT}.
  # @param value [Integer] new soot value
  def soot=(value)
    validate value => Integer
    @soot = value.clamp(0, Settings::MAX_SOOT)
  end

  # @return [Integer] the number of Gym Badges owned by the player
  def badge_count
    return @badges.count { |badge| badge == true }
  end

  #=============================================================================

  # (see Pokedex#seen?)
  # Shorthand for +self.pokedex.seen?+.
  def seen?(species)
    return @pokedex.seen?(species)
  end

  # (see Pokedex#owned?)
  # Shorthand for +self.pokedex.owned?+.
  def owned?(species)
    return @pokedex.owned?(species)
  end
end
